Create a React component with the following features:
- Has two inputs
- On entering content in the first input, it will automatically update the content in the second input

### Response:
class TwoInputsComponent extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      value1: '',
      value2: ''
    };
    this.handleChange1 = this.handleChange1.bind(this);
    this.handleChange2 = this.handleChange2.bind(this);
  }

  handleChange1(e) {
    this.setState({
      value1: e.target.value,
      value2: e.target.value
    });
  }

  handleChange2(e) {
    this.setState({
      value1: e.target.value,
      value2: e.target.value
    });
  }

  render() {
    return (
      <div>
        <input type="text" value={this.state.value1} onChange={this.handleChange1} />
        <input type="text" value={this.state.value2} onChange={this.handleChange2} />
      </div>
    );
  }
}

