### Solution:


    co_stars = {}
    max_count = 0
    most_frequent_co_star = None

    for movie in movies:
        for role in movie.roles:
            if role.actor == actor_name:
                for co_star in movie.roles:
                    if co_star.actor != actor_name:
                        if co_star.actor not in co_stars:
                            co_stars[co_star.actor] = 0
                        co_stars[co_star.actor] += 1
                        if co_stars[co_star.actor] > max_count:
                            max_count = co_stars[co_star.actor]
                            most_frequent_co_star = co_star.actor

    return most_frequent_co_star


