def find_best_outfit(fashion_items, budget):
    """
    This function takes in a list of fashion items and a budget and returns the best possible outfit within the given budget.
    It finds the items with the least cost that still result in a fashionable outfit.
    """

### Solution:


    outfit = []

    while budget > 0:
        min_cost = float('inf')
        best_item = None

        for item in fashion_items:
            if item.cost < min_cost and item not in outfit:
                min_cost = item.cost
                best_item = item

        if best_item is None:
            break

        if best_item.cost <= budget:
            outfit.append(best_item)
            budget -= best_item.cost

    return outfit


